// Overview-only entries are not advertised as live vacancies. Missing dates and
// degree rules remain unknown until an intake-specific posting is reviewed.
function overview(company,initials,country,source,rows){
 return rows.map(([id,title,areas,types,summary,structure,extra={}])=>({
  id,company,initials,country,source,title,areas,types,summary,structure,
  location:country+' · Locations vary by opening',degrees:[],start:null,duration:null,
  status:'unknown',deadline:null,closedAt:null,checked:'2026-09-24',
  eligibility:'Graduate program. Confirm the degree, graduation window and other requirements on the current employer posting.',
  notes:'The program is documented by the employer; a current application opening has not been confirmed.',...extra
 }));
}
